			BorderThickness = new Thickness(1),
			CornerRadius = new CornerRadius(8),
			Padding = new Thickness(12, 9),
			Margin = new Thickness(0, 4, 0, 4),
			Child = row
		};
		DockPanel.SetDock(container, Dock.Top);
		root.Children.Insert(1, container);
	}

